'use client'

import { useEffect, useState } from 'react'

type HealthResponse = {
  status: string
  service: string
  timestamp: string
}

type FetchState =
  | { kind: 'loading' }
  | { kind: 'ok'; data: HealthResponse }
  | { kind: 'error'; message: string }

export default function Home() {
  const [state, setState] = useState<FetchState>({ kind: 'loading' })

  useEffect(() => {
    const controller = new AbortController()
    fetch('/api/health', { signal: controller.signal })
      .then(async (res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`)
        return (await res.json()) as HealthResponse
      })
      .then((data) => setState({ kind: 'ok', data }))
      .catch((err: unknown) => {
        if (err instanceof Error && err.name === 'AbortError') return
        const message = err instanceof Error ? err.message : 'Unknown error'
        setState({ kind: 'error', message })
      })
    return () => controller.abort()
  }, [])

  return (
    <main style={{ fontFamily: 'system-ui, sans-serif', padding: '2rem', maxWidth: 720, margin: '0 auto' }}>
      <h1>Take-home exercise</h1>
      <p>Frontend &harr; Backend smoke check</p>
      <section
        style={{
          padding: '1rem 1.25rem',
          border: '1px solid #ccc',
          borderRadius: 8,
          background: '#f7f7f7',
        }}
      >
        {state.kind === 'loading' && <span>Calling <code>/api/health</code>&hellip;</span>}
        {state.kind === 'error' && (
          <span style={{ color: '#b00020' }}>
            Backend unreachable: {state.message}
          </span>
        )}
        {state.kind === 'ok' && (
          <pre style={{ margin: 0 }}>{JSON.stringify(state.data, null, 2)}</pre>
        )}
      </section>
    </main>
  )
}
{
  "name": "frontend",
  "private": true,
  "version": "0.0.0",
  "scripts": {
    "dev": "next dev",
    "build": "next build",
    "start": "next start",
    "lint": "eslint ."
  },
  "dependencies": {
    "next": "^16.0.0",
    "react": "^19.2.6",
    "react-dom": "^19.2.6"
  },
  "devDependencies": {
    "@types/node": "^24.12.3",
    "@types/react": "^19.2.14",
    "@types/react-dom": "^19.2.3",
    "eslint": "^9.0.0",
    "eslint-config-next": "^16.0.0",
    "typescript": "^5.9.0"
  }
}
# Application Source

## Overview

The browser calls the Next.js server on `/api/health`. The Next.js rewrite sends the request to the Spring Boot service, which returns the health response. `[frontend/src/app/page.tsx:Home]` `[frontend/next.config.ts:rewrites]` `[backend/src/main/java/com/global/ct/frameinventory/HealthController.java:health]`

## Subdirectories & Boundaries

- [Backend](./backend/README.md) starts Spring Boot and serves the health endpoint.
- [Frontend](./frontend/README.md) serves the smoke-check page and rewrites API requests to the backend.
# ----------------------------------------------------------------------------
# Suggested infrastructure for the Frame Inventory exercise.
#
# This compose file is a starting point, not a requirement. You are free to
# swap any of these services for tooling you prefer (a different database,
# search engine, message broker, hosting model, etc.) as long as the final
# stack still runs end-to-end with a single command.
#
# If you do choose to use the services provided here, pick ONE of the two
# datastores for your domain data — either `mongodb` or `postgres`,
# not both. Remove the service you do not need (and its volume) so the
# stack reflects the design you actually built.
# ----------------------------------------------------------------------------

services:
  backend:
    build:
      context: ./src/backend
    container_name: frame-inventory-backend
    ports:
      - "8080:8080"
      - "9090:9090"
    environment:
      SPRING_PROFILES_ACTIVE: docker
      SPRING_DATASOURCE_URL: jdbc:postgresql://postgres:5432/frames
      SPRING_FLYWAY_ENABLED: "true"
      MANAGEMENT_ENDPOINTS_WEB_EXPOSURE_INCLUDE: health,info,prometheus
      SENTRY_DSN: ${SENTRY_DSN:-}
      SENTRY_ENVIRONMENT: ${SENTRY_ENVIRONMENT:-local}
    depends_on:
      postgres:
        condition: service_healthy
      opensearch:
        condition: service_started
    networks:
      - frame-inventory

  frontend:
    build:
      context: ./src/frontend
    container_name: frame-inventory-frontend
    ports:
      - "3000:3000"
    environment:
      BACKEND_URL: http://backend:8080
    volumes:
      - ./src/frontend/src:/app/src
      - ./src/frontend/public:/app/public
    depends_on:
      - backend
    networks:
      - frame-inventory

  postgres:
    image: postgres:18.6
    container_name: frame-inventory-postgres
    ports:
      - "5432:5432"
    environment:
      POSTGRES_DB: frames
      POSTGRES_USER: app
      POSTGRES_PASSWORD: app
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -h 127.0.0.1 -U \"$$POSTGRES_USER\" -d \"$$POSTGRES_DB\""]
      interval: 2s
      timeout: 3s
      retries: 15
    volumes:
      - postgres-data:/var/lib/postgresql
    networks:
      - frame-inventory

  opensearch:
    image: opensearchproject/opensearch:2.18.0
    container_name: frame-inventory-opensearch
    environment:
      cluster.name: frame-inventory-cluster
      node.name: opensearch
      discovery.type: single-node
      bootstrap.memory_lock: "true"
      OPENSEARCH_JAVA_OPTS: "-Xms512m -Xmx512m"
      DISABLE_SECURITY_PLUGIN: "true"
      DISABLE_INSTALL_DEMO_CONFIG: "true"
    ulimits:
      memlock:
        soft: -1
        hard: -1
      nofile:
        soft: 65536
        hard: 65536
    ports:
      - "9200:9200"
      - "9600:9600"
    volumes:
      - opensearch-data:/usr/share/opensearch/data
    networks:
      - frame-inventory

  opensearch-dashboards:
    image: opensearchproject/opensearch-dashboards:2.18.0
    container_name: frame-inventory-opensearch-dashboards
    ports:
      - "5601:5601"
    environment:
      OPENSEARCH_HOSTS: '["http://opensearch:9200"]'
      DISABLE_SECURITY_DASHBOARDS_PLUGIN: "true"
    depends_on:
      - opensearch
    networks:
      - frame-inventory

  prometheus:
    image: prom/prometheus:v3.16.0
    ports:
      - "127.0.0.1:9091:9090"
    volumes:
      - ./monitoring/prometheus.yml:/etc/prometheus/prometheus.yml:ro
      - prometheus-data:/prometheus
    depends_on:
      - backend
    networks:
      - frame-inventory

  otel-collector:
    image: otel/opentelemetry-collector-contrib:0.165.0
    command: ["--config=/etc/otelcol-contrib/config.yaml"]
    ports:
      - "127.0.0.1:9464:9464"
    volumes:
      - ./monitoring/otel-collector.yml:/etc/otelcol-contrib/config.yaml:ro
    depends_on:
      - backend
    networks:
      - frame-inventory

  grafana:
    image: grafana/grafana:13.3.2
    ports:
      - "127.0.0.1:3001:3000"
    volumes:
      - ./monitoring/grafana-datasource.yml:/etc/grafana/provisioning/datasources/prometheus.yml:ro
      - ./monitoring/grafana-dashboard-provider.yml:/etc/grafana/provisioning/dashboards/frame-inventory.yml:ro
      - ./monitoring/dashboards:/etc/grafana/dashboards:ro
      - grafana-data:/var/lib/grafana
    depends_on:
      - prometheus
    networks:
      - frame-inventory

volumes:
  postgres-data:
  opensearch-data:
  prometheus-data:
  grafana-data:

networks:
  frame-inventory:
    driver: bridge
syntax = "proto3";

package frameinventory.v1;

option java_package = "com.global.ct.frameinventory.grpc.v1";
option java_multiple_files = true;
option java_outer_classname = "FramesProto";

import "google/protobuf/empty.proto";
import "google/protobuf/timestamp.proto";

service FrameManagement {
  rpc ListFrames(ListFramesRequest) returns (ListFramesResponse);
  rpc GetFrame(GetFrameRequest) returns (Frame);
  rpc GetFrameHistory(GetFrameHistoryRequest) returns (GetFrameHistoryResponse);
  rpc CreateFrame(CreateFrameRequest) returns (Frame);
  rpc UpdateFrame(UpdateFrameRequest) returns (Frame);
  rpc DeleteFrame(DeleteFrameRequest) returns (google.protobuf.Empty);
}

message ListFramesRequest {
  // Zero-based page. Defaults to 0.
  optional int32 page = 1;
  // Defaults to 25. Valid values are 1 through 50.
  optional int32 size = 2;
}

message ListFramesResponse {
  repeated Frame items = 1;
  int32 page = 2;
  int32 size = 3;
  bool has_next = 4;
}

message GetFrameRequest {
  string frame_id = 1;
}

message GetFrameHistoryRequest {
  string frame_id = 1;
}

message GetFrameHistoryResponse {
  // Newest first, with version ID descending as a tie break.
  repeated Frame versions = 1;
}

message CreateFrameRequest {
  // A case-sensitive identifier that can be used only once.
  string frame_id = 1;
  FrameData attributes = 2;
}

message UpdateFrameRequest {
  string frame_id = 1;
  // Must match the current version.
  int64 expected_version_id = 2;
  // Replaces writable attributes. Omitted optional fields are cleared.
  FrameData attributes = 3;
}

message DeleteFrameRequest {
  string frame_id = 1;
  // If absent the delete applies to the current version.
  optional int64 expected_version_id = 2;
}

message Frame {
  string frame_id = 1;
  int64 version_id = 2;
  google.protobuf.Timestamp valid_from = 3;
  google.protobuf.Timestamp valid_to = 4;
  bool current = 5;
  optional string change_source = 6;
  optional string closed_by_change_source = 7;
  // Local source timestamps in ISO 8601 format without an offset.
  optional string source_created_at = 8;
  optional string source_modified_at = 9;
  FrameData attributes = 10;
  map<string, string> external_references = 11;
  repeated string linked_frame_ids = 12;
}

message FrameData {
  // Manual writes accept LIVE, PENDING, MAINTENANCE, BLOCKED, or DRAFT.
  string status = 1;
  optional string status_reason = 2;
  optional string site_no = 3;
  optional string inventory_site_no = 4;
  optional string panel_number = 5;
  optional string location_id = 6;
  optional string environment = 7;
  optional string address = 8;
  optional string station = 9;
  optional string airport = 10;
  // Decimal strings retain PostgreSQL numeric precision.
  optional string latitude = 11;
  optional string longitude = 12;
  optional int32 distance_to_closest_school = 13;
  FrameLocation location = 14;
  FrameFormat format = 15;
  optional string size_code = 16;
  optional string aspect_ratio_code = 17;
  optional string t_size = 18;
  optional int32 pixel_height = 19;
  optional int32 pixel_width = 20;
  optional int32 illumination_type_id = 21;
  optional int32 number_of_slots = 22;
  optional string impact_weight = 23;
  bool premium = 24;
  optional string production_rate_card = 25;
  optional string production_rate_card_legacy = 26;
  optional string pricing_grade = 27;
}

message FrameLocation {
  string country_code = 1;
  string region = 2;
  string town = 3;
  string postcode = 4;
}

message FrameFormat {
  // Manual writes accept CLASSIC or DIGITAL.
  string technology = 1;
  string format_code = 2;
  string size_group_code = 3;
}

