{
  "name": "frame-inventory-bff",
  "version": "0.0.0",
  "private": true,
  "scripts": {
    "build": "proto-loader-gen-types --longs=String --defaults --grpcLib=@grpc/grpc-js --outDir=src/generated ../backend/src/main/proto/frameinventory/v1/frames.proto && tsc",
    "start": "node dist/index.js"
  },
  "dependencies": {
    "@apollo/server": "^5.0.0",
    "@grpc/grpc-js": "^1.14.0",
    "@grpc/proto-loader": "^0.8.0",
    "graphql": "^16.11.0"
  },
  "devDependencies": {
    "@types/node": "^22.0.0",
    "typescript": "^5.9.0"
  }
}

import { ApolloServer, type ApolloServerPlugin } from '@apollo/server'
import { startStandaloneServer } from '@apollo/server/standalone'
import { credentials, loadPackageDefinition, status } from '@grpc/grpc-js'
import { loadSync } from '@grpc/proto-loader'
import { GraphQLError } from 'graphql'
import { resolve } from 'node:path'
import type { ProtoGrpcType } from './generated/frames'
import type { ListFramesRequest } from './generated/frameinventory/v1/ListFramesRequest'
import type { ListFramesResponse__Output } from './generated/frameinventory/v1/ListFramesResponse'

const typeDefs = `
  type Query {
    frames(page: Int, size: Int): FramePage!
  }

  type FramePage {
    items: [Frame!]!
    page: Int!
    size: Int!
    hasNext: Boolean!
  }

  type Frame {
    frameId: ID!
    versionId: ID!
    attributes: FrameAttributes!
  }

  type FrameAttributes {
    status: String!
    address: String
  }
`

async function main() {
  const protoPath = resolve(__dirname, '../../backend/src/main/proto/frameinventory/v1/frames.proto')
  const definition = loadSync(protoPath, { longs: String, defaults: true })
  const proto = loadPackageDefinition(definition) as unknown as ProtoGrpcType
  const client = new proto.frameinventory.v1.FrameManagement(
    process.env.FRAME_GRPC_TARGET ?? 'localhost:9090',
    credentials.createInsecure(),
  )

  const closeClient: ApolloServerPlugin = {
    async serverWillStart() {
      return {
        async serverWillStop() {
          client.close()
        },
      }
    },
  }

  const server = new ApolloServer({
    typeDefs,
    plugins: [closeClient],
    includeStacktraceInErrorResponses: false,
    resolvers: {
      Query: {
        frames(_parent: unknown, args: { page?: number | null; size?: number | null }) {
          const request: ListFramesRequest = {
            page: args.page ?? undefined,
            size: args.size ?? undefined,
          }

          return new Promise<ListFramesResponse__Output>((resolve, reject) => {
            client.listFrames(request, { deadline: Date.now() + 5_000 }, (error, response) => {
              if (error?.code === status.INVALID_ARGUMENT) {
                reject(new GraphQLError(error.details, { extensions: { code: 'BAD_USER_INPUT' } }))
              } else if (error?.code === status.UNAVAILABLE || error?.code === status.DEADLINE_EXCEEDED) {
                reject(new GraphQLError('Frame service is unavailable', { extensions: { code: 'SERVICE_UNAVAILABLE' } }))
              } else if (error || !response) {
                reject(new GraphQLError('Could not list frames', { extensions: { code: 'INTERNAL_SERVER_ERROR' } }))
              } else {
                resolve(response)
              }
            })
          })
        },
      },
    },
  })

  try {
    const { url } = await startStandaloneServer(server, { listen: { port: 4000 } })
    console.log(`Frame Inventory GraphQL API available at ${url}`)
  } catch (error) {
    client.close()
    throw error
  }
}

main().catch((error: unknown) => {
  console.error(error)
  process.exitCode = 1
})

{
  "compilerOptions": {
    "target": "ES2022",
    "module": "Node16",
    "rootDir": "src",
    "outDir": "dist",
    "strict": true
  },
  "include": ["src"]
}

