import { ApolloServer } from '@apollo/server'
import { status } from '@grpc/grpc-js'
import { GraphQLError } from 'graphql'
import type { FrameManagementClient } from './generated/frameinventory/v1/FrameManagement'
import type { ListFramesRequest } from './generated/frameinventory/v1/ListFramesRequest'
import type { ListFramesResponse__Output } from './generated/frameinventory/v1/ListFramesResponse'

const typeDefs = `
  type Query {
    frames(page: Int, size: Int): FramePage!
  }

  type FramePage {
    items: [Frame!]!
    page: Int!
    size: Int!
    hasNext: Boolean!
  }

  type Frame {
    frameId: ID!
    versionId: ID!
    attributes: FrameAttributes!
  }

  type FrameAttributes {
    status: String!
    address: String
  }
`

export function createServer(client: Pick<FrameManagementClient, 'listFrames' | 'close'>) {
  return new ApolloServer({
    typeDefs,
    plugins: [
      {
        async serverWillStart() {
          return {
            async serverWillStop() {
              client.close()
            },
          }
        },
      },
    ],
    includeStacktraceInErrorResponses: false,
    resolvers: {
      Query: {
        frames(_parent: unknown, args: { page?: number | null; size?: number | null }) {
          const request: ListFramesRequest = {
            page: args.page ?? undefined,
            size: args.size ?? undefined,
          }

          return new Promise<ListFramesResponse__Output>((resolve, reject) => {
            client.listFrames(request, { deadline: Date.now() + 5_000 }, (error, response) => {
              if (error?.code === status.INVALID_ARGUMENT) {
                reject(new GraphQLError(error.details, { extensions: { code: 'BAD_USER_INPUT' } }))
              } else if (error?.code === status.UNAVAILABLE || error?.code === status.DEADLINE_EXCEEDED) {
                reject(new GraphQLError('Frame service is unavailable', { extensions: { code: 'SERVICE_UNAVAILABLE' } }))
              } else if (error || !response) {
                reject(new GraphQLError('Could not list frames', { extensions: { code: 'INTERNAL_SERVER_ERROR' } }))
              } else {
                resolve(response)
              }
            })
          })
        },
      },
    },
  })
}

const { expect, jest, test } = require('@jest/globals')
const { createServer } = require('../dist/server')

test('frames requests the specified gRPC page and returns frames with pagination metadata', async () => {
  const page = {
    items: [
      {
        frameId: 'FRAME-001',
        versionId: '9007199254740993',
        attributes: { status: 'LIVE', address: '10 Test Street' },
      },
    ],
    page: 1,
    size: 1,
    hasNext: true,
  }
  const client = {
    listFrames: jest.fn((_request, _options, callback) => callback(null, page)),
    close: jest.fn(),
  }
  const server = createServer(client)

  try {
    const response = await server.executeOperation({
      query: `
        query {
          frames(page: 1, size: 1) {
            items {
              frameId
              versionId
              attributes {
                status
                address
              }
            }
            page
            size
            hasNext
          }
        }
      `,
    })

    expect(client.listFrames).toHaveBeenCalledTimes(1)
    expect(client.listFrames).toHaveBeenCalledWith(
      { page: 1, size: 1 },
      { deadline: expect.any(Number) },
      expect.any(Function),
    )
    expect(response.body).toMatchObject({
      kind: 'single',
      singleResult: { data: { frames: page } },
    })
    expect(response.body.singleResult.errors).toBeUndefined()
  } finally {
    await server.stop()
  }
})

