const { createServer } = require('../dist/server')

test('frames requests the specified gRPC page and returns frames with pagination metadata', async () => {
  const page = {
    items: [
      {
        frameId: 'FRAME-001',
        versionId: '9007199254740993',
        attributes: { status: 'LIVE', address: '10 Test Street' },
      },
    ],
    page: 1,
    size: 1,
    hasNext: true,
  }
  const client = {
    listFrames: jest.fn((_request, _options, callback) => callback(null, page)),
    close: jest.fn(),
  }
  const server = createServer(client)

  try {
    const response = await server.executeOperation({
      query: `
        query {
          frames(page: 1, size: 1) {
            items {
              frameId
              versionId
              attributes {
                status
                address
              }
            }
            page
            size
            hasNext
          }
        }
      `,
    })

    expect(client.listFrames).toHaveBeenCalledTimes(1)
    expect(client.listFrames).toHaveBeenCalledWith(
      { page: 1, size: 1 },
      { deadline: expect.any(Number) },
      expect.any(Function),
    )
    expect(response.body).toMatchObject({
      kind: 'single',
      singleResult: { data: { frames: page } },
    })
    expect(response.body.singleResult.errors).toBeUndefined()
  } finally {
    await server.stop()
  }
})

