import {
  status,
  type CallOptions,
  type requestCallback,
  type ServiceError,
} from '@grpc/grpc-js'
import { ConstantBackoff, handleWhen, retry } from 'cockatiel'
import { GraphQLError } from 'graphql'
import { GRAPHQL_ERROR_CODES } from '../consts'
import type { ListFramesRequest } from '../generated/frameinventory/v1/ListFramesRequest'
import type { ListFramesResponse__Output } from '../generated/frameinventory/v1/ListFramesResponse'
import type { Resolvers } from '../generated/graphql'
import { logger } from '../logger'

const LIST_FRAMES_TIMEOUT_MS = 5_000
const listFramesRetry = retry(
  handleWhen(
    (error) => isGrpcError(error) && error.code === status.UNAVAILABLE,
  ),
  { maxAttempts: 2, backoff: new ConstantBackoff(100) },
)

function isGrpcError(error: unknown): error is ServiceError {
  return (
    error instanceof Error &&
    'code' in error &&
    typeof error.code === 'number' &&
    'details' in error &&
    typeof error.details === 'string'
  )
}

export interface FrameClient {
  listFrames(
    request: ListFramesRequest,
    options: CallOptions,
    callback: requestCallback<ListFramesResponse__Output>,
  ): void
  close(): void
}

export function createFrameResolvers(client: FrameClient) {
  return {
    Query: {
      async frames(_parent, args) {
        const page = args.page ?? undefined
        const size = args.size ?? undefined

        if (page !== undefined && page < 0) {
          throw new GraphQLError('Page must be 0 or greater.', {
            extensions: { code: GRAPHQL_ERROR_CODES.BAD_USER_INPUT },
          })
        }

        if (size !== undefined && (size < 1 || size > 50)) {
          throw new GraphQLError('Size must be between 1 and 50.', {
            extensions: { code: GRAPHQL_ERROR_CODES.BAD_USER_INPUT },
          })
        }

        const request: ListFramesRequest = { page, size }
        const deadline = Date.now() + LIST_FRAMES_TIMEOUT_MS
        try {
          return await listFramesRetry.execute(
            () =>
              new Promise<ListFramesResponse__Output>((resolve, reject) => {
                client.listFrames(request, { deadline }, (error, response) => {
                  if (error) {
                    reject(error)
                  } else if (!response) {
                    reject(new Error('gRPC returned no frame page'))
                  } else {
                    resolve(response)
                  }
                })
              }),
            AbortSignal.timeout(LIST_FRAMES_TIMEOUT_MS),
          )
        } catch (error) {
          const grpcError = isGrpcError(error) ? error : undefined
          if (grpcError?.code === status.INVALID_ARGUMENT) {
            throw new GraphQLError(grpcError.details, {
              extensions: { code: GRAPHQL_ERROR_CODES.BAD_USER_INPUT },
            })
          }

          if (
            grpcError?.code === status.UNAVAILABLE ||
            grpcError?.code === status.DEADLINE_EXCEEDED
          ) {
            logger.warn(
              { grpcCode: grpcError.code },
              'Frame service is unavailable',
            )
            throw new GraphQLError('Frame service is unavailable', {
              extensions: { code: GRAPHQL_ERROR_CODES.SERVICE_UNAVAILABLE },
            })
          }

          logger.error({ grpcCode: grpcError?.code }, 'Could not list frames')
          throw new GraphQLError('Could not list frames', {
            extensions: { code: GRAPHQL_ERROR_CODES.INTERNAL_SERVER_ERROR },
          })
        }
      },
    },
    Frame: {
      attributes(frame) {
        if (!frame.attributes) {
          throw new GraphQLError('Frame attributes are unavailable', {
            extensions: { code: GRAPHQL_ERROR_CODES.INTERNAL_SERVER_ERROR },
          })
        }
        return frame.attributes
      },
    },
  } satisfies Resolvers
}

